cd /filesystem/final_batch4__structural_task6_seismic_diaphragm_shear__blind && python3 -c "
import ezdxf
doc = ezdxf.readfile('project/10_drawings/architectural/A-101_Building_B_Roof_Plan_REV3.dxf')
msp = doc.modelspace()

# Get wall polylines
for e in msp:
    if e.dxftype() == 'LWPOLYLINE':
        if e.dxf.layer == 'WALL':
            print(f'WALL: {list(e.get_points())}')
        elif e.dxf.layer == 'OPENING':
            print(f'OPENING: {list(e.get_points())}')
        elif e.dxf.layer == 'ROOF':
            print(f'ROOF: {list(e.get_points())}')
        elif e.dxf.layer == 'EQUIP':
            print(f'EQUIP: {list(e.get_points())}')

print()
# Get text
for e in msp:
    if e.dxftype() in ['TEXT', 'MTEXT']:
        print(f'TEXT layer={e.dxf.layer}: \"{e.dxf.text}\" at {e.dxf.insert}')
"
